#pragma once
#include <cstdint>
namespace rig {
enum class WifiStage:uint8_t{Unconfigured,Scanning,Connecting,Authenticating,WaitingForIp,Connected,NoAccessPoint,AuthenticationFailure,ConnectionTimeout,DhcpFailure,Disconnected,RetryCountdown};
inline const char* wifiStageLabel(WifiStage s){switch(s){case WifiStage::Unconfigured:return"UNCONFIGURED";case WifiStage::Scanning:return"SCANNING";case WifiStage::Connecting:return"CONNECTING";case WifiStage::Authenticating:return"AUTHENTICATING";case WifiStage::WaitingForIp:return"WAITING FOR IP";case WifiStage::Connected:return"CONNECTED";case WifiStage::NoAccessPoint:return"AP NOT FOUND";case WifiStage::AuthenticationFailure:return"AUTH FAILED";case WifiStage::ConnectionTimeout:return"TIMEOUT";case WifiStage::DhcpFailure:return"DHCP FAILED";case WifiStage::Disconnected:return"DISCONNECTED";case WifiStage::RetryCountdown:return"RETRY WAIT";}return"UNKNOWN";}
inline const char* disconnectReasonText(int reason){switch(reason){case 2:return"AUTH EXPIRED";case 15:return"4-WAY TIMEOUT";case 201:return"AP NOT FOUND";case 202:return"AUTH FAILED";case 203:return"ASSOC FAILED";default:return"DISCONNECTED";}}
class WifiRetryState {public:void connecting(uint32_t now){stage_=WifiStage::Connecting;started_=now;next_=0;}void connected(){stage_=WifiStage::Connected;next_=0;}void fail(WifiStage failure,int reason,uint32_t now,uint32_t dwell=5000,uint32_t retry=10000){stage_=failure;reason_=reason;visibleUntil_=now+dwell;next_=now+dwell+retry;}bool update(uint32_t now){if(next_&&int32_t(now-visibleUntil_)>=0)stage_=WifiStage::RetryCountdown;return next_&&int32_t(now-next_)>=0;}void retryNow(){next_=0;stage_=WifiStage::Connecting;}uint32_t countdown(uint32_t now)const{return next_&&int32_t(next_-now)>0?(next_-now+999)/1000:0;}WifiStage stage()const{return stage_;}int reason()const{return reason_;}private:WifiStage stage_=WifiStage::Unconfigured;int reason_=0;uint32_t started_=0,visibleUntil_=0,next_=0;};
}
